configuration.tbelDecoder:
// 1. Parsing sicuro del wrapper ThingsBoard
var data = decodeToJson(payload);
if (!data) {
    try {
        data = JSON.parse(payloadBytesToString(payload));
    } catch (e) {
        data = {};
    }
}

// 2. Estrazione del payload effettivo e del topic MQTT
var topic = metadata ? metadata.topic : (data.topic || "");
var p = data.payload ? data.payload : data;

// 3. Estrazione dinamica del nome dispositivo (dal topic o dal payload)
var deviceName = "sensore_001"; // Fallback di default
if (topic) {
    var topicParts = topic.split('/');
    if (topicParts.length >= 2 && topicParts[1]) {
        deviceName = topicParts[1]; // Estrae "sensore_001" da "spore/sensore_001/data"
    }
} else if (p.device_id) {
    deviceName = String(p.device_id);
}

// 4. Estrazione sicura dei sotto-oggetti
var hw = p.hw || {};
var analysis = p.analysis || {};
var ram = hw.ram || {};
var disk = hw.disk || {};

// 5. Costruzione telemetria (gestisce sia il JSON completo che il test {"prova": true})
var cleanTelemetry = {};

if (p.prova !== undefined) {
    // Se invii il pacchetto di test
    cleanTelemetry.prova = p.prova;
} else {
    // Pacchetto reale Biosensore
    cleanTelemetry.spore_count = Number(analysis.spore_count || 0);
    cleanTelemetry.detected = analysis.detected ? 1 : 0;
    cleanTelemetry.frame_id = Number(p.frame_id || 0);
    cleanTelemetry.sample_id = String(p.sample_id || "");
    cleanTelemetry.cpu_temp_c = Number(hw.cpu_temp_c || 0);
    cleanTelemetry.processing_time_s = Number(hw.processing_time_s || 0);
    cleanTelemetry.ram_used_percent = Number(ram.used_percent || 0);
    cleanTelemetry.disk_used_percent = Number(disk.used_percent || 0);
}

// 6. Output richiesto da ThingsBoard
return {
   deviceName: deviceName,
   deviceType: "Optical Biosensor",
   telemetry: cleanTelemetry
};
